import module java.base;

void main(String[] args) {
    String fileArg = null;
    String since = null;
    String level = null;
    int top = 5;

    int i = 0;
    while (i < args.length) {
        String a = args[i];
        switch (a) {
            case "--help" -> {
                printHelp();
                System.exit(0);
            }
            case "--since" -> {
                if (i + 1 >= args.length) {
                    System.err.println("error: missing value for --since");
                    System.exit(2);
                }
                since = args[++i];
            }
            case "--level" -> {
                if (i + 1 >= args.length) {
                    System.err.println("error: missing value for --level");
                    System.exit(2);
                }
                level = args[++i];
            }
            case "--top" -> {
                if (i + 1 >= args.length) {
                    System.err.println("error: missing value for --top");
                    System.exit(2);
                }
                String v = args[++i];
                try {
                    top = Integer.parseInt(v);
                } catch (NumberFormatException e) {
                    System.err.println("error: invalid value for --top: " + v);
                    System.exit(2);
                }
                if (top < 0) {
                    System.err.println("error: invalid value for --top: " + v);
                    System.exit(2);
                }
            }
            default -> {
                if (a.startsWith("-") && !a.equals("-")) {
                    System.err.println("unknown flag: " + a);
                    System.exit(2);
                }
                if (fileArg != null) {
                    System.err.println("error: unexpected argument: " + a);
                    System.exit(2);
                }
                fileArg = a;
            }
        }
        i++;
    }

    if (since != null && !isValidTimestamp(since)) {
        System.err.println("error: invalid value for --since: " + since);
        System.exit(2);
    }
    if (level != null && !isValidLevel(level)) {
        System.err.println("error: invalid value for --level: " + level);
        System.exit(2);
    }

    BufferedReader reader;
    if (fileArg == null || fileArg.equals("-")) {
        reader = new BufferedReader(new InputStreamReader(System.in, StandardCharsets.UTF_8));
    } else {
        Path path = Path.of(fileArg);
        try {
            reader = Files.newBufferedReader(path, StandardCharsets.UTF_8);
        } catch (IOException e) {
            System.err.println("error: cannot read " + fileArg);
            System.exit(2);
            return;
        }
    }

    long total = 0;
    long debugCount = 0;
    long infoCount = 0;
    long warnCount = 0;
    long errorCount = 0;
    String first = null;
    String last = null;

    Map<String, Integer> groupCounts = new LinkedHashMap<>();
    Map<String, String> groupDisplay = new LinkedHashMap<>();

    try (reader) {
        String line;
        while ((line = reader.readLine()) != null) {
            int sp1 = line.indexOf(' ');
            if (sp1 < 0) continue;
            int sp2 = line.indexOf(' ', sp1 + 1);
            if (sp2 < 0) continue;
            String ts = line.substring(0, sp1);
            String lvl = line.substring(sp1 + 1, sp2);
            String message = line.substring(sp2 + 1);
            if (message.isEmpty()) continue;
            if (!isValidTimestamp(ts)) continue;
            if (!isValidLevel(lvl)) continue;

            if (since != null && ts.compareTo(since) < 0) continue;
            if (level != null && !lvl.equals(level)) continue;

            total++;
            switch (lvl) {
                case "DEBUG" -> debugCount++;
                case "INFO" -> infoCount++;
                case "WARN" -> warnCount++;
                case "ERROR" -> errorCount++;
            }
            if (first == null) first = ts;
            last = ts;

            if (lvl.equals("ERROR")) {
                String normalized = normalize(message);
                groupCounts.merge(normalized, 1, Integer::sum);
                groupDisplay.putIfAbsent(normalized, message);
            }
        }
    } catch (IOException e) {
        System.err.println("error: cannot read " + (fileArg == null ? "-" : fileArg));
        System.exit(2);
        return;
    }

    List<String> keys = new ArrayList<>(groupCounts.keySet());
    keys.sort((k1, k2) -> {
        int c1 = groupCounts.get(k1);
        int c2 = groupCounts.get(k2);
        if (c1 != c2) return Integer.compare(c2, c1);
        return groupDisplay.get(k1).compareTo(groupDisplay.get(k2));
    });

    IO.println("total: " + total);
    IO.println("by level: DEBUG=" + debugCount + " INFO=" + infoCount + " WARN=" + warnCount + " ERROR=" + errorCount);
    IO.println("first: " + (total == 0 ? "n/a" : first));
    IO.println("last: " + (total == 0 ? "n/a" : last));
    IO.println("top errors:");
    int shown = 0;
    for (String key : keys) {
        if (shown >= top) break;
        IO.println("  " + groupCounts.get(key) + " " + groupDisplay.get(key));
        shown++;
    }
}

static final Set<String> LEVELS = Set.of("DEBUG", "INFO", "WARN", "ERROR");

static final Pattern UUID_PATTERN = Pattern.compile(
        "[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}");
static final Pattern HEX_PATTERN = Pattern.compile(
        "\\b(?=[0-9a-fA-F]*[a-fA-F])[0-9a-fA-F]{6,}\\b");
static final Pattern DIGIT_PATTERN = Pattern.compile("[0-9]+");

static final DateTimeFormatter TS_FMT = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
        .withResolverStyle(ResolverStyle.STRICT);

boolean isValidLevel(String s) {
    return LEVELS.contains(s);
}

boolean isValidTimestamp(String s) {
    if (s.length() != 19) return false;
    try {
        LocalDateTime.parse(s, TS_FMT);
        return true;
    } catch (DateTimeParseException e) {
        return false;
    }
}

String normalize(String message) {
    String m = UUID_PATTERN.matcher(message).replaceAll("<uuid>");
    m = HEX_PATTERN.matcher(m).replaceAll("<hex>");
    m = DIGIT_PATTERN.matcher(m).replaceAll("<num>");
    return m;
}

void printHelp() {
    IO.println("Usage: logsum [FILE] [--since TIMESTAMP] [--level LEVEL] [--top N]");
    IO.println();
    IO.println("Streaming summary of a log file (or stdin).");
    IO.println();
    IO.println("Arguments:");
    IO.println("  FILE               Log file to read (omit or use '-' for stdin)");
    IO.println();
    IO.println("Options:");
    IO.println("  --since TIMESTAMP  Only consider lines with timestamp >= TIMESTAMP (format: YYYY-MM-DDTHH:MM:SS)");
    IO.println("  --level LEVEL      Only consider lines at exactly this level (DEBUG, INFO, WARN, ERROR)");
    IO.println("  --top N            Number of top error groups to show (default: 5)");
    IO.println("  --help             Show this help message");
}

